    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Mottagaren behåller samma hemlighet och använder den exakt som den är, inklusive whsec_-prefixet, som HMAC-nyckel för X-Cbox-Signature.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Inloggningssidan har din logotyp och dina färger. Personer skriver in sitt lösenord där, så den ska tydligt vara din sida.',
    'your_workspace_its_projects_team_keys_and_billing_sign_d55c648f' => 'Din arbetsyta med projekt, team, nycklar och fakturering. Inloggningen till dina appar ställs in i respektive miljös konsol.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'En funktionsflagga är en inställning som appar frågar efter för en person i en organisation. Aktivera den för utvalda användare, organisationer eller en andel av alla användare. Alla appar får samma svar via token-claimen `feature_flags` eller utvärderingsendpunkten, utan ny driftsättning. En användarregel går före en organisationsregel, som går före utrullningen, som går före standardvärdet.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'En nyckel låter dina skript och integrationer anropa en apps API som dig utan inloggning. Den får aldrig göra mer än du får i appen. Om din åtkomst minskar förlorar nyckeln också de rättigheterna. Nyckeln visas en gång, så kopiera den när du skapar den och återkalla den direkt om den läcker eller inte längre används.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'En behörighet är en sak som en roll får göra, till exempel skapa fakturor eller läsa rapporter. Du kan definiera egna behörigheter här utan kod och sedan sätta ihop dem till roller. Appar kan också registrera sina automatiskt så att listan följer vad appen faktiskt kontrollerar. Dina egna behörigheter kan du ändra; miljöns delade behörigheter får du använda men inte ändra.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'En telefon med autentiseringsappen besvarar godkännandeförfrågningar och meddelar när någon loggar in som dig. Registrera den genom att skanna koden. Ta bort den här omedelbart om du förlorar telefonen; då kan den inte längre godkänna något.',
    'a_project_is_one_idp_product_this_workspace_owns_and_it_a5e40dff' => 'Ett projekt är en identitetsleverantörsprodukt som arbetsytan äger, och dess miljöer hör till projektet. Innan arbetsytan har skapat ett projekt i sin egen konsol finns inget att välja eller öppna här. Den här sidan skapar inget projekt åt arbetsytan.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Ett projekt är en av dina produkter med eget abonnemang, inloggning och miljöer som produktion och staging. Öppna en miljö härifrån för att administrera den. Skapa ett nytt projekt när du lanserar en produkt som ska köras och faktureras separat.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'En roll är en arbetsuppgift som dina appar förstår, till exempel redaktör eller supportmedarbetare. Du bestämmer vem som har vilken roll här, och varje app bestämmer vad dess roller får göra. Roller följer personen in i anslutna appar, så att du kan ge och återkalla åtkomst på ett ställe.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'En granskning där du går igenom vem som har vilka roller och bekräftar att de fortfarande behövs. Behörigheter samlas lätt på hög när personer byter team men behåller gamla rättigheter. Granskningen hjälper dig att rensa. Återkallelser tillämpas när den stängs, och hela omgången dokumenteras för revisorn.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Ett schema beskriver hur en åtgärds händelser ska se ut: måltyper och metadata. Händelser med schema kontrolleras när de kommer in. Utan schema accepteras de som skickade, om inte strikt läge är aktiverat.',
    'a_workspace_is_one_signed_up_company_s_home_on_this_ins_3053f712' => 'En arbetsyta är ett registrerat företags hem i installationen, med projekt, miljöer och team. Öppna den för att hantera produkter och miljöer. Om du stänger av den loggas medlemmarna ut och inloggning stoppas i alla dess miljöer.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Åtkomst samlas på hög. Personer byter team men behåller gamla behörigheter tills en revisor frågar. En granskning tar en ögonblicksbild av nuvarande tilldelningar och kräver ett beslut om varje rättighet fortfarande behövs.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Lägg till personen i en organisation nedan för att ge åtkomst där. Om apparna inte har egna hyresgäster kan du i stället ge en administratörs- och supportroll som gäller i hela miljön.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'En administratörs- och supportroll ges till egen personal, till exempel support och drift, för hela miljön. Den gäller i alla organisationer och kan inte ses, tilldelas eller tas bort av deras administratörer. En approll som tilldelas så gäller fortfarande bara den appen.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'En administratörs- och supportroll ges till egen personal för hela miljön. Den gäller i alla organisationer och kan inte ses eller ändras av deras administratörer.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'En agent är programvara som arbetar i miljön med en hanteringsnyckel: en AI-assistent som Claude Code eller Cursor, en intern bot eller din backend. Ge varje agent en egen nyckel med bara de behörighetsomfång som behövs. Bestäm vilka åtgärder som kräver ditt godkännande och återkalla nyckeln direkt när arbetet är klart eller något verkar fel.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Ett API är en tjänst som tar emot åtkomsttoken, till exempel https://api.example.com. Registrera det med de behörighetsomfång det förstår. Du bestämmer vilka av dem appar som registreras av organisationerna får begära. En token för API:et anger dess adress som mottagare, vilket tjänsten kontrollerar.',
    'an_environment_is_a_fully_isolated_identity_service_wit_fed9a3d8' => 'En miljö är en helt isolerad identitetstjänst med egna användare, nycklar, inloggning och utfärdare. Här listas alla miljöer i installationen med sin arbetsyta. Skapa en miljö, välj den i konsolen och konfigurera dess första organisation och administratör.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'En miljö är helt isolerad med egna användare, nycklar, inloggning och utfärdare. Skapa din första ovan och konfigurera sedan en organisation med en administratör.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'En identitetsleverantör som importerar tjänsteleverantörsmetadata använder denna URL i stället för separata värden för entitets-ID och ACS-URL. Den fungerar redan innan identitetsleverantörens uppgifter har fyllts i.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'En organisation samlar användare, inloggningsmetoder och roller. Skapa en ovan eller konfigurera miljöns första organisation och administratör från sidan Miljöer.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Organisationens egen leverantör ersätter miljöns på dess inloggningssida. Även organisationer som stängt av miljöns leverantör listas. Det tar bara bort knappen; det är kravet på SSO som hindrar andra inloggningssätt.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'API-nycklar och token för externa tjänster som appar och agenter behöver lagras krypterat här i stället för i varje apps konfiguration. Lägg in en hemlighet en gång och ge utvalda appar rätt att använda den. Den visas aldrig igen, så förnya den om du tappar bort den.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API-nycklar som appar och agenter använder hos andra tjänster. Varje värde lagras krypterat, lämnas bara till uttryckligen behöriga appar och visas aldrig igen efter lagring.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Appar som vill agera för en av dina användare. Varje användare godkänner sina egna förfrågningar. Avslå bara här om det ser ut som missbruk; avslaget registreras i revisionsloggen.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Appar med egna användarlistor kommer ur synk så snart någon börjar eller slutar. En SCIM-anslutning skickar varje ändring direkt, även avslutade anställningar som annars lätt glöms bort.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID skickar ett signerat meddelande till din endpoint efter en händelse, till exempel en ny medlem eller ändrad roll. Då kan dina system reagera utan ständig hämtning. Leveranser görs om vid behov. Endpointen informeras i efterhand och kan inte påverka åtgärden.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Bekräfta det som fortfarande behövs och återkalla resten. Inget tillämpas innan granskningen stängs. En återkallad administratörs- och supportroll tas då bort i alla organisationer samtidigt.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Välj SCIM om leverantören skickar data till oss, Google Workspace eller Entra om vi ska hämta dem, eller ditt HR-system som Workday, BambooHR, Rippling, HiBob eller Personio så att personer får konto på startdatumet.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code öppnar webbläsaren för inloggning här och frågar vad du vill tillåta. Ingen nyckel behöver förvaras. Alla MCP-klienter som loggar in med OAuth fungerar på samma sätt med denna URL.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Avgränsa med kommatecken eller blanksteg. Ett inskrivet behörighetsomfång saknar API-ägare och hamnar oförändrat i appens token. Det kan aldrig ange ett registrerat API som mottagare; använd listorna ovan för det.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Skapa, ändra, aktivera, inaktivera och ta bort SSO-anslutningar, kräva SSO för en organisation samt verifiera och aktivera SSO-rutning för dess e-postdomäner. Ändrar hur personer loggar in.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Skapar organisationen, dess ägare, dess första produkt och produktens produktionsmiljö. Ägaren får en länk via e-post för att välja sitt eget lösenord; du väljer inget åt personen.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Definiera, ersätta och ta bort scheman för validering av revisionshändelser samt ändra lagringstiden. Kortare lagringstid tar bort äldre händelser permanent.',
    'deleting_this_workspace_tears_down_every_project_and_en_f26b2e2f' => 'Om arbetsytan tas bort försvinner alla dess projekt och miljöer. För att skydda aktiva identitetsleverantörer går det inte att göra själv. Kontakta supporten för att fortsätta.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Varje organisation är ett företag eller team som använder produkten, med egna medlemmar, roller, domäner och SSO. Skapa en per företag som registrerar sig. Öppna den för att hantera medlemmar, inbjudningar och verifierade domäner eller för att stänga av den.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Varje pipeline låter personer ansluta sina egna konton hos tjänster som GitHub, Google eller Slack. Token lagras krypterat och hålls aktuella här. Behöriga appar begär en fungerande token när de anropar tjänsten som personen och lagrar aldrig en själva.',
    'each_project_in_your_workspace_has_its_own_plan_and_env_c5ff35b1' => 'Varje projekt i arbetsytan har eget abonnemang och miljöutrymme. Här visas de tillsammans med månadens användning: organisationer, debiterade SSO-anslutningar och inloggningar. Prissättningen räknar månatligt aktiva användare och företagsanslutningar som SSO och SCIM. Sandboxmiljöer har ingen anslutningsavgift.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Hela miljön: alla med ett konto i miljön kan logga in i appen, oavsett organisation. Välj en organisation om det inte är avsikten.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Radera en person permanent (GDPR artikel 17): inloggningsuppgifter, sessioner, medlemskap och personuppgifter tas bort och kontot pseudonymiseras. Kan inte ångras.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Utvärderas i ordning: blockeringslistan, tillåtlistan, dina regler uppifrån med första träffen som beslut, sedan de inbyggda reglerna där den striktaste träffen avgör. Utan träff tillåts åtkomst.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Varje åtgärd accepteras som appen skickar den. Lägg till ett schema för att kontrollera dess händelser när de kommer in. En konsekvent logg säkerställs när händelsen skrivs, inte först när den läses.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Varje administrativ ändring av medlemmar, roller, anslutningar eller appar registreras här direkt, med vem som gjorde den och när. Ingen konfiguration behövs.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'API-nycklar i appkonfigurationer eller miljöfiler kan inte förnyas centralt eller dras in snabbt. Här lagras de krypterat, tilldelas per app och kan återkallas med ett klick.',
    'every_api_key_the_people_in_this_organization_have_crea_15e73625' => 'Alla API-nycklar som personer i organisationen har skapat för dess appar. Återkalla nycklar som har läckt eller inte längre används. Personer skapar egna nycklar under Mitt konto.',
    'every_api_key_the_people_in_this_organization_have_crea_fe7787a7' => 'Alla API-nycklar som personer i organisationen har skapat för dess appar: innehavare, app, behörigheter och senaste användning. En nyckel får bara göra det innehavaren får och slutar fungera när personen lämnar. Återkalla läckta eller oanvända nycklar. Varje person skapar sina egna under Mitt konto.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Varje app som loggar in personer via Cbox ID eller anropar dess API registreras här och får egna uppgifter. Registrera en per app och miljö. Dela aldrig inloggningsuppgifter mellan dem, så kan en återkallas utan att de andra slutar fungera.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Alla webbläsare och enheter där du är inloggad, appar du har gett tillåtelse att agera för dig samt senaste inloggningar och säkerhetsändringar. Om något är okänt, logga ut sessionen eller återkalla appens åtkomst och byt sedan lösenord.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Varje ändring i organisationen: vem som gjorde vad, med vilket objekt och när. Posterna länkas med hashvärden, så en ändrad eller borttagen post bryter kedjan och upptäcks. Loggen är avsiktligt skrivskyddad och är underlaget du lämnar till en revisor.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Alla anslutningar mellan Cbox ID och andra system på ett ställe: SSO, social inloggning, katalog- och HR-synkronisering, utgående provisionering, SAML-appar, webhooks, hooks, loggströmmar och pipelines. Varje katalogkort öppnar rätt inställningssida. Anslutningar visar alla befintliga anslutningar med status, felaktiga först.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Alla organisationer i miljön som är vald i konsolen, som ett träd med återförsäljare, organisationerna de hanterar och underenheter. Skapa eller stäng av en organisation, eller flytta den under en annan överordnad organisation.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Alla sidor du öppnar från och med nu, som organisationer, användning och organisationsdetaljer, läser den miljöns data. Ingenting ändras i någon av miljöerna.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Alla personer med en identitet i miljön, oavsett organisation. Öppna en person för att återställa lösenord eller tvåfaktor, avsluta sessioner, inaktivera kontot, ändra organisationer och roller eller radera personen permanent efter en begäran om radering.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Alla återkallelser i granskningen tillämpas nu. Ogranskade poster följer granskningspolicyn, som som standard återkallar åtkomsten. Detta kan inte ångras.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Alla hemligheter som just nu autentiserar appen. Bara en hash av varje lagras. Listan visar de sista fyra tecknen så att du kan identifiera vilken hemlighet en installation använder.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Alla token som utfärdats med den återkallas nu, och nya inloggningar kan inte använda den. Appar som kontrollerar token själva accepterar dem tills de går ut, senast när sessionen slutar.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Alla inloggningsmetoder med status och var de ändras: lösenord, passkeys, e-postlänk, social inloggning, Enterprise SSO och andra faktor. De flesta styrs av miljön, medan SSO-anslutningar hör till organisationerna. Om installationen begränsar en metod visas det tillsammans med inställningens namn.',
    'every_workspace_on_this_install_open_one_to_walk_its_pr_4abbea51' => 'Alla arbetsytor i installationen. Öppna en för att hantera produkter och miljöer. Om den stängs av loggas medlemmarna ut och autentisering stoppas i alla dess miljöer.',
    'everyone_who_administers_this_workspace_the_built_in_ro_26825e5f' => 'Alla som administrerar arbetsytan, deras inbyggda roll (Ägare, Administratör, Utvecklare, Medlem eller Läsare) och tillgängliga miljöer. Bjud in via e-post och ge bara de miljöer som arbetet kräver.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Alla som kan logga in i organisationen och dina ännu inte accepterade inbjudningar. Bjud in via e-post. Personerna konfigurerar sin egen inloggning, så att du aldrig behöver hantera deras lösenord.',
