    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 En kod kan stjälas genom SIM-kortsbyte eller obehörig nummerflytt, fångas upp i telefonnätet eller skrivas in på en trovärdig falsk inloggningssida. Den är ändå mycket säkrare än bara ett lösenord. Aktivera den för personer som inte kan använda en autentiseringsapp eller en passkey.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 En logotyp som länkades från en annan webbplats avslöjade för den webbplatsen vilka som öppnade din inloggningssida. Därför visar värdbaserade sidor nu bara bilder som laddats upp här. Ladda upp den under :part2 nedan eller ta bort den för att dölja meddelandet.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 En roll är en beteckning i token. Roller som en app definierar är skrivskyddade här; övriga definierar du själv. Varje medlem har också exakt en :part2 :part3 :part4 (ägare, administratör, utvecklare, medlem eller läsare), som avgör vad personen får administrera i den här konsolen.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '”:part1” tillhör redan ett annat API i den här miljön. En tokenbegäran anger ett behörighetsområde enbart med dess nyckel, så varje nyckel kan bara tillhöra ett API.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 tillhör ett API som appen inte får använda. De utelämnas från alla token. Ta bort dem från de inskrivna behörighetsområdena.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 kan logga in med lösenord eller med den här anslutningen. Om enkel inloggning krävs avvisas alla andra inloggningssätt, så att inte heller redan utfärdade åtkomstuppgifter kan kringgå leverantören du just konfigurerade. De flesta företag som ansluter en IdP vill ha detta, men läs först vad det innebär.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 har inga behörigheter ännu, så :part2 är :part3 tomt. Rollnamnet finns fortfarande kvar och kan användas.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 är redan konfigurerat för den här organisationen. Ändra inloggningsuppgifterna eller ta bort anslutningen först.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 erbjuds inte längre. Alla som loggade in med det behåller sitt konto och kan fortfarande använda sitt lösenord.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 är avstängt på alla inloggningssidor. Inloggningsuppgifterna sparas så att du kan aktivera det igen.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 är avstängt på den här organisationens inloggningssida. Inloggningsuppgifterna sparas så att du kan aktivera det igen.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 är ditt enda sätt att logga in. Ange ett lösenord eller lägg till en passkey innan du kopplar från det.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 är din organisations enkla inloggning. Det är så organisationen identifierar dig, så anslutningen kan inte kopplas från här.',
    '_part1_its_team_is_administered_under_workspace_team_by_939d535a' => ':part1 Teamet administreras under Arbetsyta › Team av någon med en arbetsyteroll, inte härifrån.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Inget här styrs ännu av :part3. Om du ändrar något nedan blir det organisationens egen regel.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 uppdaterade, :part3 avprovisionerade,:part4 :part5 överhoppade, :part6 grupper :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Uppdatera mottagaren först: från nästa försök avvisar den alla leveranser som den inte kan verifiera.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 avvisar inloggningen om detta inte stämmer exakt. Värdet sparas för den här konfigurationen, så du kan klistra in det i :part2 nu och spara här efteråt.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 – sessioner, passkeys och andrafaktorer, profiler hos identitetsleverantörer, katalogdata, utfärdade token, rolltilldelningar och granskningshistorik finns kvar och kan återaktiveras.',
