    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Vad en app kan få göra i detta API. Bara :part1:s egna appar får ha dessa behörigheter.',
    'what_is_part1_00d3f3e7' => 'Vad är :part1?',
    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Det du administrerar och uppgifterna dina appar behöver för integrationen. :part1',
    'withdraw_access_for_part1_10961483' => 'Återkalla appen :part1:s åtkomst',
    'withdraw_the_invitation_to_part1_13c82934' => 'Återkalla inbjudan till :part1',
    'withdraw_the_invitation_to_part1_fafedcae' => 'Återkalla inbjudan till :part1?',
    'you_can_also_part1_part2_part3_53f32513' => 'Du kan också :part1 :part2 .:part3',
    'you_can_turn_it_off_again_on_part1_part2_sessions_that_89d71a9d' => 'Du kan stänga av det igen på :part1 :part2. Avslutade sessioner förblir avslutade.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'Du har inga behörigheter i :part1, så en nyckel skulle bara identifiera dig där.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Din ändpunkt verifierar huvudet :part1 i varje begäran med den här hemligheten.',
    'your_roles_using_permission' => 'I :count av dina roller|I :count av dina roller',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Allt som organisationen har konfigurerat och det som återstår. Checklistan visar det faktiska läget. Varje steg bockas av automatiskt när det är klart.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Hela varumärkesupplevelsen på en sida: den värdbaserade inloggningens logotyp, favicon, färger, typsnitt och hörn med direktförhandsvisning, samt produktnamn, e-postavsändare och välkomstmeddelande. Ange inställningarna en gång för hela miljön så ärvs de av alla organisationer, eller ge en organisation ett eget utseende på fliken Branding.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Från nästa försök nekar blockeringar inloggningar och registreringar i den här miljön, medan kontrollkrav kräver ytterligare verifiering. En felaktig regel kan stänga ute riktiga personer.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Bevilja en till de personer som stödjer eller kör dina appar. En apps egen roll når endast den appens tokens; en roll för alla appar når var och en av dem.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Antalet organisationer, användare, SSO-anslutningar, appar och användarsynkroniseringar i miljön, med länkar till respektive sida. Genvägarna nedanför används för att skapa det som oftast behövs: en organisation, en användare, en SSO-anslutning eller en app.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Antalet personer som har loggat in och hur ofta apparna har anropat API:et under de senaste 30 dagarna. Översikten hjälper dig att bedöma belastningen och upptäcka avvikelser. Den är ingen faktura.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Hur ofta data hämtas och vilka fält från HR-systemet som kopieras till varje person, till exempel kostnadsställe eller plats. Om du ändrar fälten blir nästa körning en fullständig synkronisering.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Så exporteras granskningsloggen från Cbox ID: en schemalagd export skickar nya poster till ditt SIEM eller arkiv var femte minut. Ett dagligt lagringsjobb skapar en kontrollpunkt i loggen utan att radera något. Här kan du hämta en persons granskningshistorik för en begäran om tillgång enligt GDPR eller kontrollera i en miljökonsol att exporterna körs.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Om appen senare anger en annan URL återkallas godkännandet och du tillfrågas igen. En ändring av vart lösenord skickas får inte göras utan ditt godkännande. Delegerad inloggning används under övergången till det nya systemet. När få personer återstår i det gamla systemet stänger du av den och skickar dem en länk för att återställa lösenordet.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Knappen tas bort och inloggningsuppgifterna raderas. Alla som har loggat in med anslutningen behåller sitt konto och kan fortfarande använda sitt lösenord. Stäng av anslutningen i stället om du vill behålla inloggningsuppgifterna.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Dess behörighetsområden tas också bort. Appar som hade dem behåller dem som inskrivna behörighetsområden som inte längre ger åtkomst till detta API. Redan utfärdade token fungerar tills de löper ut.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Nycklar till en miljös hanterings-API: administrera organisationer, medlemmar, inbjudningar, roller och appar i en miljö från din egen backend. Varje nyckel har uttryckligen angivna behörighetsområden.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Nycklar som organisationens användare har skapat för dess appar, med behörigheterna för varje nyckel. Användarna skapar sina egna nycklar. Återkalla nycklar som har läckt eller inte längre används.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Lämna fältet tomt för nästan alla leverantörer. Deras ID-token verifieras mot signeringsnycklarna som publiceras i discovery-dokumentet (jwks_uri), även när nycklarna roteras. Klistra bara in leverantörens offentliga PEM-nyckel om inga nycklar publiceras.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Låt personer logga in med ett konto de redan har. Konfigurera en leverantör en gång för miljön så erbjuds den av alla organisationer. En organisation kan i stället använda egna inloggningsuppgifter eller stänga av en leverantör.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Låt användarna av dina appar ansluta sina egna GitHub-, Google-, Slack- eller Salesforce-konton, så att apparna kan anropa dessa API:er för deras räkning. Deras token lagras krypterade, förnyas här och görs tillfälligt tillgängliga endast för de appar du ger tillstånd.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Låter dina användare logga in med sitt befintliga företagskonto hos Microsoft Entra ID, Okta eller Google Workspace i stället för ett separat lösenord här. Du ansluter identitetsleverantören en gång och verifierar dina e-postdomäner. Alla med dessa domäner skickas sedan till leverantören för att logga in.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Inloggning med Entra ID, Okta eller Google Workspace ingår i Enterprise-planen. Kontakta ditt kundteam för att aktivera den för den här organisationen.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Fortfarande giltiga länkar som har lämnats till organisationens IT-administratör. En återkallad länk slutar fungera direkt. Inställningar som redan har gjorts via länken behålls.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Söker efter en organisation via namn eller kortnamn, eller en användare via namn eller e-post, i alla miljöer i installationen och inte bara i den aktuella konsolens miljö. Använd sökningen när någon behöver hjälp och du inte vet vilken miljö personen finns i.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Metadatascheman använder en delmängd av JSON Schema: ett objekt med egenskaper av typen sträng, tal, heltal, booleskt värde eller null, med regler för tillåtna värden, längd, intervall, mönster och format. En sparad ändring skapar en ny version. Redan registrerade händelser behåller den version som de validerades mot.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Skickar varje ny granskningsloggpost direkt till säkerhetsteamets verktyg, till exempel ett SIEM. Konfigurera detta så att utredningar kan börja i verktyg teamet redan använder, utan att först behöva begära en export. Leverans sker minst en gång, så enstaka dubbletter kan förekomma.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'För de flesta integrationer passar webhooks bättre. De körs efter händelsen och kan inte blockera förloppet. Använd en hook bara när ditt system måste kunna påverka en inloggning eller utfärdandet av en token medan det pågår.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Ingen ny hemlighet utfärdas. Från nästa leveransförsök, även återförsök, används den andra metodens headers. En mottagare som inte har uppdaterats avvisar då varje leverans.',
    'nobody_is_on_this_workspace_it_has_no_owner_so_nobody_c_554101fb' => 'Arbetsytan har inga medlemmar och ingen ägare, så ingen kan logga in för att administrera den. Det tyder på ett fel vid etableringen som bör undersökas, inte bara en tom lista.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Inga poster nekas alltid eller undantas från reglerna. Blockera ett adressintervall som har använts för attacker, eller undanta kontorsnätverket från reglerna för inloggningsfrekvens.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Visar Google, GitHub, Apple och andra leverantörer som knappar på inloggningssidan för personer som hellre använder ett befintligt konto än skapar ännu ett lösenord. Konfigurera en leverantör en gång för miljön så erbjuds den av alla organisationer. En organisation kan använda egna inloggningsuppgifter eller stänga av en leverantör. Du anger inloggningsuppgifterna; resten fylls i automatiskt. En e-postadress från en leverantör räcker aldrig ensam för att få åtkomst till ett befintligt konto här.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Aktiverat för den här andelen av alla som inte omfattas av reglerna ovan. En stabil hash av användar-ID:t väljer samma personer varje gång; en höjning lägger bara till fler. Lämna tomt om ingen gradvis utrullning ska ske.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'En markerad händelse (siem.stream.test) skickas nu med strömmens inställningar och inloggningsuppgifter, utan kö och utan återförsök. Om det lyckas försvinner även markeringen ”Åtgärd krävs”.',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'En post per rad, inklusive protokoll, till exempel https://app.example.com. Om någon rad är ogiltig avvisas hela listan. Felaktiga rader tas inte bort utan meddelande.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'En `type` per resurstyp, med dess `relation`-poster under. En relation avgörs av subjekt som anges direkt i en tupel ([user, group#member]), en annan relation (owner), en relation på ett överordnat objekt (viewer from parent) eller en kombination med or, and eller but not.',
    'one_workspace_on_this_install_its_team_its_projects_and_e343ed1c' => 'En arbetsyta i installationen med sitt team, sina projekt och alla miljöer som tillhör projekten. Om arbetsytan stängs av loggas medlemmarna ut och autentisering stoppas i alla dessa miljöer.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Endast för leverantörer som inte publicerar signeringsnycklar (jwks_uri) i sitt discovery-dokument. Annars hämtas nycklarna därifrån, även efter rotation. Ange en offentlig PEM-nyckel. Den lagras krypterad och visas aldrig igen. Lämna tomt för att behålla den nuvarande nyckeln.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Endast aktiva medlemmar i den valda organisationen kan logga in i den här applikationen. Alla andra nekas, och avslaget registreras i granskningsloggen.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Organisationsinformation i målmiljön: medlemmar, SSO, domäner, tilldelade rättigheter och senaste aktivitet. Det enda som kan ändras på den här sidan är organisationens status.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organisationer, användare och aktiva sessioner i alla miljöer i installationen samt organisationerna med flest medlemmar. Vyn läser bara data och ändrar aldrig vilken miljö konsolen visar.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Välj det ramverk du bygger med, så skapas en app med omdirigering till din lokala utvecklingsserver, miljövariabler att klistra in och kod för inloggning. Sidan väntar tills någon faktiskt loggar in. Nedanför finns stegen som gör appen till en produkt: varumärkesanpassning, organisationer, SSO, en agent, en kollega och produktion. Varje steg bockas av automatiskt utifrån vad miljön innehåller, aldrig manuellt.',
    'platform_operators_administer_every_workspace_and_envir_fb24c050' => 'Plattformsoperatörer administrerar alla arbetsytor och miljöer i installationen på en överordnad nivå. Lägg bara till operatörer som ansvarar för själva installationen och stäng av deras åtkomst när det inte längre är deras uppgift.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Anslut en identitetsleverantör till vår SCIM-ändpunkt, anslut Google Workspace eller Microsoft Entra, eller koppla ditt HR-system: Workday, BambooHR, Rippling, HiBob eller Personio. Vi hämtar personaluppgifterna från de anslutna systemen enligt ett schema.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Verifiera vilka e-postdomäner organisationen äger. En verifierad domän kan skicka alla med en adress på den direkt till organisationens SSO-anslutning.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar bedömer varje inloggning och registrering: försök med stulna inloggningsuppgifter, botliknande hastighet, geografiskt omöjliga förflyttningar, nya enheter, anonymiserande nätverk och engångsadresser samt dina egna regler och tillåtelse- och blockeringslistor. Varje beslut loggas. När du aktiverar tillämpningen blockerar Radar åtkomst eller kräver en andra faktor. Granska besluten här innan du aktiverar tillämpningen och när någon uppger att det inte går att logga in.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar bedömer varje inloggning och registrering: försök med stulna inloggningsuppgifter, botliknande hastighet, geografiskt omöjliga förflyttningar, nya enheter, anonymiserande nätverk och engångsadresser samt dina egna regler och listor. Skälen till besluten loggas.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Neka lösenord som finns i kända dataläckor. Kontrollen görs mot Have I Been Pwned utan att lösenordet någonsin skickas. Om tjänsten inte kan nås tillåts registreringen i stället för att blockeras.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registrerar applikationer som accepterar den här miljön som SAML-identitetsleverantör. Användarna loggar då in med sina befintliga konton här. Koppla varje applikation till dess organisation så att bara organisationens medlemmar får logga in. Utan koppling är den öppen för alla i miljön. Detta är den utgående riktningen. Använd företags-SSO under Autentisering för inloggning med ett företagskonto som finns hos en annan leverantör.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Förfrågningar visas här automatiskt när en app eller agent behöver ditt godkännande för att agera för din räkning. Du behöver inte göra något innan dess. Neka förfrågningar som du inte själv har initierat.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Förfrågningar från agenter som vill agera för en användares räkning visas här när de kommer in. Varje användare godkänner sina egna förfrågningar. På den här sidan kan du neka sådant som verkar vara missbruk.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Just nu loggar personer in med inloggningsuppgifter som lagras här. Anslut din leverantör så kan de använda sitt befintliga företagskonto. När du stänger av kontot hos leverantören förlorar de omedelbart åtkomsten här.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Behörighetsområden, utloggnings-URI:er, tokeninställningar och rollmanifestets URL kopieras oförändrade. Hemligheter, nycklar och appens användare kopieras inte. De tillhör miljön där de skapades.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Se appen precis som en av dess användare: du loggar in som personen av ett angivet skäl och i högst en timme. Appen får veta vem du egentligen är och får inget sätt att hålla sessionen aktiv. Organisationens granskningslogg visar vem som gjorde det och varför.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Skicka engångslänken till den som konfigurerar din identitetsleverantör. Den löper snart ut och fungerar utan ett konto. Kopiera den nu; den visas bara en gång.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Skicka engångslänken till den som administrerar organisationens identitetsleverantör, om personen inte redan har fått den via e-post. Den fungerar utan ett konto tills den löper ut. Kopiera den nu; den visas bara en gång.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Tillhandahåller miljöns identitetsändpunkter på en domän som du äger, till exempel login.example.com, i stället för vår. Du bekräftar ägarskapet med en DNS-TXT-post. Konfigurera detta om användarna bara ska se din egen adress när de loggar in.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Ange detta som rollens förtroendepolicy (IAM › Roles › Trust relationships). Plattformen får bara anta rollen när den anger strömmens externa ID. Ingen annan på plattformen kan då rikta en ström mot din roll.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Inloggningar och begäranden som Cbox ID har bedömt som tillräckligt riskfyllda för att markeras, med de senaste först samt riskpoäng och motivering. Granska detta efter en ökning av misslyckade inloggningar eller när någon rapporterar en inloggning som de inte har gjort.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Inloggningar, utfärdade token, nya användare och aktiverad tvåfaktorsautentisering, dag för dag under de senaste 30 dagarna om installationen inte använder en annan period. Sidan förblir tom tills den som driver installationen har konfigurerat lagring för analysdata.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Tar en ögonblicksbild av alla administratörs- och supportroller i hela miljön som poster att intyga eller återkalla. En återkallelse tar bort rollen i alla organisationer samtidigt.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Programvara som arbetar i den här miljön med en hanteringsnyckel, till exempel Claude Code, Cursor, en intern bot eller din egen backend. Varje program har bara de behörighetsområden du har tilldelat och väntar på ditt godkännande för de åtgärder du har valt.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Vissa roller får aldrig tilldelas samma person. Den som skapar en betalning bör inte också godkänna den. Ange dessa rollpar här. Cbox ID blockerar nya tilldelningar som bryter mot regeln och visar vilka personer som redan har båda rollerna.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF och Generic JSON är HTTP-mottagare som du anger en URL för. Datadog, Amazon S3 och Google Cloud Storage använder egna inställningar.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Börja med exemplet med dokument i mappar: ägare, redigerare och läsare, där mappens åtkomsträttigheter ärvs av allt innehåll. Tupler och behörighetskontroller kräver först ett schema.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Funktionsväxlar som apparna frågar efter för en person i en organisation. Aktivera en funktion för angivna användare, organisationer eller en andel av alla personer. Alla appar får samma svar, i token eller via API:et.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'Adressen som token för detta API anger som målgrupp och som API:et kontrollerar. Den kan inte ändras senare, eftersom redan utfärdade token innehåller värdet.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'Agentens begäran nekas och agenten kan inte agera för personens räkning. Avslaget registreras i granskningsloggen och kan inte ångras. Agenten måste göra en ny begäran.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Granskningshändelser som appen skickar för varje organisation den betjänar: vem som gjorde vad i produkten och när. De lagras per organisation i en hashkedja och visas för organisationens egna administratörer. Använd detta när en organisation begär en granskningslogg för sitt konto. Definiera scheman för att hålla händelserna enhetliga.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Granskningshändelser som appen skickar för alla organisationer den betjänar, med de senaste först. Varje organisations händelser bildar en egen hashkedja.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Granskningsloggen finns här och säkerhetsteamets verktyg finns någon annanstans. En ström skickar varje ny post direkt till verktygen, så att en utredning inte behöver börja med en begäran om CSV-export.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Knappen försvinner från organisationens inloggningssida. Miljöns egen leverantör ersätter den inte. Inloggningsuppgifterna behålls, så att du kan aktivera anslutningen igen.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'Den övre gränsen för appens åtkomst. En begränsning gäller från nästa token. Om en enhet eller agent begär ett behörighetsområde som du tar bort nekas begäran, i stället för att få mindre åtkomst utan meddelande.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'Mottagaren avvisade inställningarna, till exempel på grund av en saknad bucket eller fel region eller plats. Inget levereras förrän inställningarna är rättade. Posterna ligger kvar och väntar; de kastas inte bort.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Organisationens e-postdomäner, var och en verifierad med en DNS-TXT-post. När en domän är verifierad kan du aktivera obligatorisk omdirigering, så att alla med en adress på domänen skickas till företagets SSO i stället för lösenordsinloggning. Verifiera därför alla domäner som användarna har adresser på innan du förlitar dig på SSO.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per_42243556' => 'Nycklarna som din egen kod använder för att anropa Cbox ID, med en flik per typ. En hemlig hanteringsnyckel låter din backend administrera organisationer, medlemmar, inbjudningar, roller och appar i en miljö. En arbetsytenyckel anropar arbetsytans API med en inbyggd roll. En publicerbar nyckel används i en webbläsarapp och fungerar bara från tillåtna origins. Hemliga nycklar och arbetsytenycklar visas bara en gång. Kopiera dem när de skapas och återkalla dem direkt om de läcker.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Den omvända riktningen: Cbox ID skickar användarna till företagets andra SaaS-produkter via deras SCIM-ändpunkter. Du hanterar tillägg och avslut av användare på ett ställe i stället för i en egen administrationspanel hos varje leverantör.',
    'the_name_of_your_workspace_which_your_projects_environm_3fa3245f' => 'Namnet på arbetsytan där dina projekt, miljöer och team finns, och som visas i hela konsolen. Att radera en arbetsyta stänger ned alla dess inloggningsmiljöer. Därför görs det genom en supportbegäran, inte en knapp.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Lösenordsregler, kontospärrar samt krav på tvåfaktorsautentisering och SSO vid varje inloggning. För hela miljön styrs också om passkeys och inloggningslänkar erbjuds och hur länge sessioner varar. Miljön anger grundregler som alla organisationer ärver. Organisationer kan skärpa lösenords- och tvåfaktorsreglerna, men aldrig försvaga dem.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Dina tjänster som tar emot åtkomsttoken och de behörighetsområden som varje tjänst äger. Du bestämmer vem som får en registrerad API:s behörighetsområden. Ingen kan bara skriva in ett sådant i en app för att få åtkomst till API:et.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Hela miljön erbjuder leverantören på alla inloggningssidor. Välj en organisation för att konfigurera en egen leverantör i stället. Den ersätter då miljöns leverantör på organisationens inloggningssida.',
    'the_workspace_s_own_keys_for_the_workspace_api_list_pro_d42a9e3f' => 'Arbetsytans egna nycklar till arbetsytans API: lista projekt och miljöer, skapa miljöer samt lista och bjuda in teammedlemmar. Varje nyckel har en inbyggd roll.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Personens sessioner och token återkallas. Passkeys, andrafaktorer, medlemskap, rolltilldelningar, API-token, hemligheter i valvet, enheter och alla lagrade kopior av personuppgifterna raderas. Kontot behålls bara som en pseudonymiserad, inaktiverad post. Appar som synkroniserar personer härifrån får en begäran om radering. Granskningsloggen behåller personens opaka ID, inte namn eller e-postadress.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Dessa hookar körs under en åtgärd, inte efteråt, och svaret påverkar resultatet. Din ändpunkt kan lägga till information i en token eller neka en inloggning helt. De ingriper direkt i flödet, så en långsam eller trasig ändpunkt påverkar personen som försöker logga in.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Personen förlorar omedelbart åtkomsten till alla plattformssidor i installationen. Befintliga sessioner slutar fungera vid nästa begäran. Du kan återaktivera personen här.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Detta kan inte ångras. Inloggningsuppgifter, medlemskap och personuppgifter raderas och kontot pseudonymiseras. Om personen är ensam ägare till en organisation måste ägarskapet överföras först.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Installationen saknar Turnstile-nycklar (CBOX_ID_TURNSTILE_SITE_KEY), så det finns ingen Turnstile-kontroll att aktivera. Vid en markerad registrering verifieras e-postadressen i stället.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Ändpunkten tillhör miljön och körs för varje organisation i den. Den visas här eftersom den körs vid dina inloggningar. Den hanteras av operatören.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Den här miljön erbjuder en MCP-server vid sidan av REST-API:et. Anslut en agent med en hanteringsnyckel, så kan den utföra exakt det som nyckelns behörighetsområden tillåter, med samma kontroller, godkännanden och granskningslogg som konsolen.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Den här miljön erbjuder en MCP-server, standardgränssnittet för AI-assistenters verktygsanrop, vid sidan av REST-API:et. Ange adressen och en hanteringsnyckel i Claude Code, Cursor eller en annan MCP-klient. Agenten kan utföra exakt det som nyckelns behörighetsområden tillåter, med samma kontroller och granskningslogg som konsolen.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Användaren kan inte längre logga in i någon applikation i miljön. Befintliga sessioner slutar fungera vid nästa begäran. Uppgifterna behålls och du kan återaktivera användaren när som helst.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Användaren äger eller administrerar en organisation. Sådana konton får inte impersoneras, eftersom det skulle kunna ge varaktig kontroll över organisationen till den som övertar identiteten.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'I dag läggs personer till och tas bort här manuellt. Anslut företagets befintliga katalog så sköts båda delarna automatiskt, även borttagningarna som annars lätt glöms.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Innan ett API har registrerats är ett behörighetsområde bara text i en app. Alla som får redigera appen kan tilldela den valfria behörighetsområden. Registrera API:erna som apparna anropar så att deras behörighetsområden får en ägare.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Verifierade domäner leder personer till din egen identitetsleverantör. Funktionen ingår i Enterprise-planen. Kontakta ditt kundteam för att aktivera den för organisationen.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'När du verifierar en domän du äger, till exempel acme.com, kan Cbox ID känna igen dina användare via e-postadressen och skicka dem direkt till leverantören. Då behöver ingen välja rätt inloggningsknapp.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooks, utloggningsmeddelanden till anslutna appar, hämtning av rolluppdateringar och köad e-post hanteras i bakgrunden av köarbetare, utan att personen behöver vänta. Om ingen köarbetare körs behandlas inget av detta, trots att resten av konsolen ser normal ut. På den här sidan upptäcker du problemet.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Åtgärder som agenter i miljön väntar på godkännande för. Om nyckeln kräver godkännande stannar agenten och frågar personen som skapade nyckeln. Personen kan svara på telefonen eller här. Den som administrerar miljön kan neka misstänkta förfrågningar. Nedanför visas appars förfrågningar om att agera som en användare; dessa godkänner varje användare själv.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Vad en app kan få göra i detta API. Dina egna appar kan få alla behörighetsområden. Appar registrerade av en organisation kan bara få dem som är markerade för organisationer.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Åtgärder som programvara i miljön väntar på godkännande för. En agent vars nyckel kräver godkännande stannar och frågar personen som skapade nyckeln. Svara här eller på telefonen.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Nyckeln som din kod frågar efter och som claim-fältet feature_flags innehåller. Gemena bokstäver och siffror, med - _ eller . mellan dem. Nyckeln kan inte ändras senare.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'När en app eller AI-agent behöver ditt godkännande för att agera för din räkning kan den inte alltid fråga på skärmen framför dig. Därför visas förfrågan här. Godkänn bara förfrågningar som du själv har startat och kontrollera att koden stämmer med koden på enheten som frågar.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'När ALLA villkor är uppfyllda utför Radar regelns åtgärd och prövar inga efterföljande regler. Dessa regler prövas efter tillåtelse- och blockeringslistorna och före de inbyggda reglerna.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Dit Cbox ID skickar personer efter utloggning från appen. URI:n som appen begär måste finnas här exakt, även med ett eventuellt avslutande snedstreck. Annars stannar personen på Cbox ID:s utloggningssida. Lämna tomt om appen aldrig begär en återgång.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Var du är inloggad, vad som kan agera för din räkning och vad som har hänt med kontot. Om du ser något du inte känner igen loggar du ut den sessionen och byter lösenord.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Under övergången från ett annat system kan appen ange sin gamla inloggningsändpunkt i manifestet, tillsammans med rollerna. Den visas här för ditt godkännande innan den används.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Under övergången från ett annat system kan en app begära att e-postadress och lösenord för personer som ännu inte finns i Cbox ID kontrolleras mot den gamla inloggningsändpunkten. Testa ändpunkten innan du godkänner den. Personer som den accepterar skapas här och skickas aldrig dit igen. Om ändpunkten ligger nere kan de som ännu inte har flyttats inte logga in.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Utan roller får alla som kan logga in de rättigheter appen ger vanliga användare. Med roller anger du en gång vilka som exempelvis är redigerare och vilka som arbetar med support. Alla anslutna appar kan följa den indelningen.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Skapa en regel som tillåter, kräver extra verifiering eller blockerar utifrån vad du vet om användarna. Kräv till exempel extra verifiering för inloggningar utanför länderna där ni verkar, eller undanta kontorsnätverket från reglerna för inloggningsfrekvens.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Du agerar som personen, i personens session och med personens åtkomst. Tiden är begränsad till 30 minuter och åtkomsten är skrivskyddad där konsolen kan upprätthålla det. Varje begäran registreras under ditt namn.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Du förlorar åtkomsten direkt. Som ägare kan du bara lämna organisationen när någon annan äger den. Överför ägarskapet först eller radera organisationen under Inställningar.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Appens egen åtkomstmodell: resurstyper som dokument och mappar, relationer som ägare, redigerare och läsare samt hur de ärvs. Den som får läsa en mapp kan till exempel läsa alla dokument i den. Appen lagrar vem som har vilken relation till vilken resurs och frågar vid varje begäran: ”får den här användaren redigera dokumentet?”. Schemat avgör svaret.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Appens egen åtkomstmodell: resurstyper, relationerna för varje typ och hur de ärvs. Appen skriver tupler — vem som har vilken relation till vad — och kontrollerar behörigheter vid varje begäran.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Appen skickar dessa händelser med ett anrop per grupp. Varje händelse anger organisationen där den inträffade. De visas här och för organisationens egna administratörer när de kommer in.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Miljöns standardprofil: den värdbaserade inloggningens utseende, logotyp och favicon samt namnet och avsändaren som användarna ser. Alla organisationer ärver profilen om de inte anger en egen.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Din identitetsleverantör skapar, uppdaterar och inaktiverar personer här automatiskt via standarden SCIM. När någon börjar eller slutar i HR-systemet når ändringen apparna inom några sekunder, utan ärenden eller kvarlämnade konton — särskilt viktigt när någon slutar.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Dina egna inloggningsmetoder och aktiva sessioner. En passkey ger starkast skydd och är snabbast att använda: enheten låser upp den med fingeravtryck eller ansiktsigenkänning, och det finns inget lösenord att stjäla genom nätfiske.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Mottagaren behåller samma hemlighet. En hexhemlighet med 64 tecken blir whsec_ följt av strängens base64-kodning — "whsec_" + base64(secret). En hemlighet som redan börjar med whsec_ används oförändrad.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => ':part1 saker att göra, ungefär i den här ordningen. Varje punkt bockas av automatiskt när den verkligen är klar. Du behöver inte markera något som färdigt manuellt.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "personens id",
  "org": "organisationen som personen företräder",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'En API-nyckel (Organisationsinställningar › API-nycklar), inte en applikationsnyckel. Den lagras krypterad och visas aldrig igen. :part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Inloggningsmetoderna för :part1. Utgångspunkten är miljöns standardinställningar. Ändringar här kan bara göra reglerna strängare.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Medlemmarna loggas ut och alla tillhörande :part1 slutar hantera autentisering från och med nästa begäran. Avstängningen kan hävas här.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'Tillhörande :part1 loggas ut, och alla tillhörande :part2 slutar hantera autentisering från och med nästa begäran. Avstängningen kan hävas här.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Organisationens :part1 kan inte längre logga in i den, och appar som använder den för autentisering kan inte längre autentisera dem. Underorganisationer stängs inte av samtidigt. Du kan återaktivera organisationen här.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minuter, högst :part1. Ett tomt fält använder installationens standardvärde :part2. En förkortning avslutar även pågående sessioner som överskrider den nya gränsen.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Behövs bara om appen kräver mer från :part1 än själva inloggningen. Separera värdena med mellanslag. De scopes som behövs för inloggning begärs alltid.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Klistra in hela JSON-nyckelfilen för ett tjänstekonto som har rollen roles/storage.objectCreator för denna bucket. Den lagras krypterad och visas aldrig igen. :part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Sandlådemiljöer tillåter localhost-adresser och skickar aldrig riktiga e-postmeddelanden. :part1 återstår i projektets plan.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Logga in i en av dina appar som :part1 för att se personens vy. Appen informeras om att det är du som agerar, och organisationens granskningslogg registrerar vem, när och varför.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'Appen vars deklarerade roller och behörigheter finns i token för detta API. Bara appar som ägs av :part1 kan väljas.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Alternativen på inloggningssidan för :part1. Leverantörer ärvs från miljön. Organisationen kan stänga av en leverantör eller ersätta den med en egen.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'När en agents nyckel kräver godkännande för en åtgärd visas begäran här och på telefonen till personen som skapade nyckeln. Den väntar i upp till :part1.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Vilka inloggningssätt :part1 erbjuder utöver lösenord och hur länge en inloggning gäller. Inställningarna är desamma för alla organisationer i miljön.',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Claim-fältet :part2 betyder något annat: det anger vad en :part3 :part4 fick begära, inte vad denna :part5 får göra.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 De används inte för att logga in i den här konsolen. Administratörer loggar in via Cbox ID på :part2 med de inloggningsmetoder som finns där.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Välj scope :part2 :part3 när du registrerar appen. ID-token innehåller då samma rollnamn i claim-fältet :part4 – det namn som Kubernetes, Grafana och Vault förväntar sig. Inget mer behöver skapas.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Du agerar som :part2 :part3 för att ge support. Allt du gör loggas. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'En hanteringsnyckel gäller bara i sin egen miljö. Exportera appens ritning (GET /apps/{id}/blueprint) och registrera den med den andra miljöns nyckel (POST /apps med `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'En hanteringsnyckel för en agent. Den tillåter bara det som dess scopes medger. De åtgärder du väljer väntar på ditt godkännande – på telefonen eller på :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'En sida på :part1. Lämna fältet tomt för att öppna konsolen, med :part2 angivet i inbjudan.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Ett :part1 är identitetsleverantör för en produkt. Det innehåller separata :part2 :part3 – produktion och sandlåda – med egna användare, nycklar och inloggning, och faktureras enligt en egen plan.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'En behörighet anger vad en :part1 får göra efter inloggning. Vad en :part2 får begära styrs av ett scope som du anger vid registreringen under :part3 :part4.',
    'a_workspace_key_reaches_the_workspace_itself_projects_e_28317ec8' => 'En arbetsytenyckel når själva arbetsytan – projekt, miljöer, team och nycklar – men inte innehållet i en miljö. Skapa en under :part1 :part2 :part3 på plattformens rotnivå.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Åtkomsttoken för den här appen anger :part1 som målgrupp :part2. API:et bör bara godta token som anger det som målgrupp.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Åtkomsttoken för den här appen anger miljöns utfärdare, :part1 :part2, som målgrupp. Det ändras när appen får ett scope från något av dina registrerade API:er.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Lägg till en TXT-post på :part1 :part2 med värdet nedan och klicka sedan på Verifiera. Det kan ta några minuter innan DNS-ändringarna slår igenom.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'En app registrerar sin katalog via SDK:t. :part1 :part2 Du kan skapa rollen nu och välja dess behörigheter när nycklarna har kommit in.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Applikationer som litar på den här miljön som SAML-identitetsleverantör. Använd :part1 :part2 om personer ska kunna logga in med ett konto som de redan har hos en annan leverantör.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Godkännanden gäller hanterings-API:ets åtgärder. Dessa scopes används av slutpunkter som ännu inte räknas som åtgärder och körs därför utan att fråga: :part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Appar skickar personer till registrering med :part1 och ber inloggade personer att skapa en organisation med :part2. Båda alternativen är bara tillgängliga när detta är aktiverat.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Frågan ställs precis som appen ställer den (:part1), med alla arv som schemat definierar.',
    'auth_settings_differ' => ':count inställning skiljer sig från din miljö.|:count inställningar skiljer sig från din miljö.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_fbee6c88' => 'Anslut en gång på plattformens rotnivå i stället för separat för varje miljö. Med din inloggning nås arbetsytan, alla miljöer i den som du administrerar och ditt eget konto. Ett miljöverktyg tar argumentet :part1 :part2 och REST-API:et tar headern :part3 för att ange var åtgärden ska utföras. Åtkomsten begränsas till dina behörigheter och det du tillåter. Varje kritisk åtgärd väntar på ditt godkännande på din enhet.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Varje nytt konto skapar och äger sin egen organisation. Appar kan också be en inloggad person att skapa en med :part1 :part2.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Varje organisation ger personen en :part1, som styr vad personen får administrera där, och valfritt antal :part2, som styr vad personen får göra i organisationens appar.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Miljön ”:part1” har skapats. Lägg till :part2 i miljöns domäninställningar för att verifiera domänen via DNS. En overifierad domän kan inte vara utfärdare.',
    'environments_nest_under_a_project_and_a_project_under_a_03ba63b6' => 'Miljöer tillhör ett projekt, och projekt tillhör en :part1 :part2 :part3. Börja där för att se hela arbetsytans innehåll. Två typer av poster tillhör aldrig en arbetsyta: :part4 är miljön som själva installationen körs i och där plattformsoperatörernas och arbetsytans medlemmars konton finns. En :part5 :part6-miljö saknar projekt, faktureras därför inte och kan inte nås från någon arbetsyta. Inget av fallen är ett fel som ska rättas här, och inget av dem kan omfördelas på den här sidan.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Alla sätt att logga in på :part1, om de är aktiverade och var de ändras. Organisationer kan ställa strängare krav – :part2 :part3.',
    'every_workspace_environment_and_operator_on_part1_a_sus_e4247a2d' => 'Alla arbetsytor, miljöer och plattformsoperatörer på :part1. En avstängning, en ny miljö eller en ändring av operatörer här gäller över hela plattformen.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Funktionsflaggan ”:part1” har skapats. Den är avstängd för alla tills en regel nedan eller standardinställningen aktiverar den.',
    'framework_3cf574caed49' => 'Behörighetsområdena :value1 tillhör ett registrerat API vars behörighetsområden den här klienten inte får ha. En organisationsägd klient kan ha behörighetsområden för den egna organisationens API:er samt sådana för miljöns API:er som organisationer får begära.',
    'framework_43fd205dea6a' => 'Scope [:key] tillhör redan ett annat API i den här miljön. Scope-nycklar är unika inom en miljö eftersom en tokenbegäran bara anger scope med dess nyckel.',
    'framework_47867973811e' => 'Katalogsynkroniseringen med :provider misslyckades: :request begränsades av en anropsgräns (HTTP :status) efter :attempt försök.',
    'framework_5eb368b0fb37' => 'Workday: Rapportens URL måste vara rapportens webbtjänstadress: …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'Appen [:clientId] måste ha samma ägare som det API vars åtkomstregler den upprätthåller. En koppling skulle föra in en ägares roller och behörigheter i en annan ägares token.',
    'framework_87da9891b0ad' => 'Katalogsynkroniseringen med :provider misslyckades: :request var inte tillgänglig (HTTP :status) efter :attempt försök.',
    'framework_98eb4683e38b' => 'Katalogsynkroniseringen med :provider misslyckades: :request misslyckades (HTTP :status): hittades inte. Kontrollera kontot, underdomänen eller rapportadressen.',
    'framework_a934fd6a0c26' => '[:origin] använder http, så nyckeln och allt sidan gör med den skulle skickas okrypterat över nätverket. Använd https, eller en loopback-värd som http://localhost:3000 under utvecklingen.',
    'framework_b63785ee57fb' => 'Katalogsynkroniseringen med :provider misslyckades: :request misslyckades (HTTP :status): autentiseringsuppgifterna ger inte behörighet att läsa medarbetardata.',
    'framework_e5ca82ab9dff' => 'Katalogsynkroniseringen med :provider misslyckades: :request misslyckades (HTTP :status): autentiseringsuppgifterna nekades.',
    'framework_fc1964a8e8c4' => 'Detta är den sista giltiga hemligheten för klienten [:clientId]. Rotera hemligheten för att ersätta den. Om den återkallas kan klienten inte längre autentisera sig.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Om slutpunkten är :part1 kan personer som ännu inte har migrerats inte logga in. De som redan har migrerats påverkas inte.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'I den ordning de visas. Om du stänger av en av miljöns leverantörer här tas bara knappen bort från sidan. Det går fortfarande att logga in med leverantören på andra ställen. Kräv SSO under :part1 :part2 om din identitetsleverantör ska vara det enda inloggningssättet.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Nycklar börjar med detta prefix, så att en nyckel i en logg kan kopplas till appen: :part1 :part2. 2–16 gemena bokstäver eller siffror, följt av :part3 eller :part4 :part5, unikt i den här miljön. Om du anger ett prefix aktiveras nycklar. Om du tar bort det stoppas nya nycklar; befintliga fortsätter att fungera tills de återkallas.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Lista funktionsflaggor med deras målgruppsregler och utvärdera varje flagga för en användare i en organisation. Det är vad appens backend begär när den inte har någon token.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Lista katalogerna (SCIM, Google Workspace, Microsoft Entra) som synkroniserar in personer, deras grupper och synkroniseringsfel. Bearer-token och leverantörernas inloggningsuppgifter lämnas aldrig ut.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Lista SAML- och OIDC-anslutningar som organisationer använder för inloggning samt e-postdomäner som leder personer till dem. Certifikat, klienthemligheter och signeringsnycklar lämnas aldrig ut.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Lista tredjepartsleverantörer som personer kan ansluta sina konton till, vilka appar som får tillfällig åtkomst till dessa token och vilka personer som har anslutit. Klienthemligheter och token lämnas aldrig ut.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Skapa och återkalla engångslänkar till administratörsportalen. Med länken kan organisationens IT-administratör konfigurera SSO, domäner eller katalogsynkronisering utan ett konto. En ny länk visas bara en gång.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Det finns ännu inga roller att mappa till. Definiera en under :part1 :part2 eller låt en app deklarera sina egna roller.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_462fe672' => 'Ingen i den här organisationen har skapat en nyckel för någon av dess appar. Användarna skapar egna nycklar under Mitt konto för en app som har aktiverat API-nycklar för medlemmar i sina inställningar: :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Ingen är inloggad i en app som någon av dessa personer. Starta en sådan session från en persons sida under :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Bara konsolen kan ge en app :part1, inte en hanteringsnyckel eller en agent som agerar åt dig. Bevilja det i konsolen på appens sida för scopes.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Bara sådant som du själv får göra i :part1 erbjuds. Om du senare förlorar en behörighet förlorar nyckeln den också.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Lägger till nycklarna för de funktionsflaggor som är aktiverade för personen i organisationen där personen loggade in som claim-fältet `feature_flags` i åtkomsttoken, ID-token och UserInfo.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Lägger personens ROLLER i ID-token under namnet `groups`, som Kubernetes, Grafana, Vault och många äldre SaaS-appar förväntar sig. Det finns inget objekt som heter grupp i den här konsolen. Skapa en roll med namnet som appen förväntar sig, så visas den där.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Läsa Radars läge, inbyggda och egna regler, tillåtelse- och blockeringslistor samt beslutsvyn: varför en inloggning eller registrering tilläts, krävde extra verifiering eller blockerades. IP- och e-postadresser från beslut lämnas aldrig ut.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Läsa granskningshändelser som appen har skickat och exporter av dem, verifiera en organisations händelsekedja och läsa tillhörande scheman och lagringsregler.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Läsa behörighetsschemat och dess tupler samt göra behörighetskontroller och listfrågor, till exempel ”får användaren redigera dokumentet?” eller ”vilka dokument får personen se?”. Endast de rättigheter som appens backend behöver för att kontrollera åtkomst.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Ersätt auktoriseringsschemat: resurstyperna och reglerna för varje relation. Det ändrar omedelbart resultatet för alla behörighetskontroller i miljön.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Roller som gäller i hela miljön, i varje organisation och även utan organisationstillhörighet. Organisationer kan aldrig se dessa roller. :part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Sandlådemiljö – endast för testning. Detta är :part1 din produktionsinloggning, och inga riktiga e-postmeddelanden skickas.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Scope ”:part1” har tagits bort. Appar som hade det behåller det som ett manuellt angivet scope, som inte längre ger åtkomst till detta API.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'De första :part1 visas. Sök efter resten. Det du redan har markerat ligger kvar i listan.',
    'sms_allowed_country_count' => 'Godtas som andra faktor i :count land.|Godtas som andra faktor i :count länder.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Uppgifterna för en person som :part1 skickas aldrig. Lösenordet är det som finns i Cbox ID, och det gamla systemet har inget inflytande över det.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'När en person loggar in och är :part1 skickas e-postadressen och lösenordet till den slutpunkten. Om svaret är ja skapas personen här, och uppgifterna skickas aldrig dit igen.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Lagra, rotera och återkalla inloggningsuppgifter för externa tjänster samt ge eller återkalla en apps rätt att använda dem tillfälligt. Detta gäller inte behörighetsområdena vault.manage / vault.lease i appens egen token.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Varje begäran innehåller :part1 :part2 – en hanteringsnyckel för den här miljön.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Har du fastnat på någon punkt? Varje sida i konsolen har en :part1 :part2 :part3 bredvid rubriken med en kort förklaring och en länk till hela guiden.',
    'suspension_is_the_only_lever_here_and_it_is_reversible_84455a59' => 'Här kan du bara stänga av en arbetsyta eller återaktivera den. Inget på sidan raderar en arbetsyta eller tömmer dess data. Installationen innehåller även miljöer utan arbetsyta: plattformens rotmiljö och eventuella kvarvarande miljöer utan koppling. Båda är tydligt märkta under :part1 :part2.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Den här sidan ändrar bara avstängningen, som kan hävas. Att välja och öppna en miljö ändrar bara vad konsolen visar. Ingen av miljöerna ändras.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'SMS-koder till :part1 slutar fungera. Autentiseringsappen, passkeys och återställningskoder påverkas inte. Om telefonnumret var personens enda andra faktor skyddas kontot bara av lösenordet tills en ny faktor registreras.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Certifikatet har redan gått ut (:part1). Ladda ned det aktuella certifikatet från din identitetsleverantör.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Detta favicon kan inte användas. Skicka själva bilden som en base64-kodad data:-URI (data:image/png;base64,…). Externa bildadresser accepteras inte. Varje besökare hämtar bilden på inloggningssidan, och en extern bildserver skulle då få information om besökarna.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Många e-postmeddelanden har begärts. Försök igen om :part1 sekunder eller kontrollera skräppostmappen under tiden.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Nu är alla punkter på listan klara. Framöver återvänder du främst till konsolen vid behov. Två delar är värda att kontrollera regelbundet: :part1 :part2 :part3 och :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Den här logotypen kan inte användas. Skicka själva bilden som en base64-kodad data:-URI (data:image/png;base64,…). Externa bildadresser accepteras inte. Varje besökare hämtar bilden på inloggningssidan, och en extern bildserver skulle då få information om besökarna.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'E-postdomänerna som dina organisationer har gjort anspråk på. En verifierad domän skickar alla med en adress på den till organisationens anslutning: :part1 :part2. Varje domän verifieras på organisationens sida.',
    'the_platform_s_own_environment_on_part1_how_every_works_07c8a7ac' => 'Plattformens egen miljö på :part1: här loggar alla arbetsyteägare och plattformsoperatörer in i Cbox ID, och här sker inloggningen till alla miljökonsoler. En ändring gäller för samtliga dessa inloggningar.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Rollen [:part1] kan inte tilldelas i den här organisationen. Den tillhör en annan organisation eller en app som organisationen inte får använda.',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'Det finns ingen klienthemlighet att klistra in. :part1 kräver i stället en signerad assertion, som vi skapar med nyckeln ovan för varje inloggning och förnyar i god tid innan den löper ut.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Det finns ännu ingen roll att tilldela. Definiera en på sidan :part1 :part2 :part3 eller låt en app deklarera sina egna roller i sitt manifest.',
    'these_are_the_buttons_on_part1_how_every_workspace_owne_5c0655c0' => 'Det här är knapparna på :part1 som arbetsyteägare och plattformsoperatörer använder för att logga in i Cbox ID och därmed i alla miljökonsoler. Administratörerna för dessa använder Cbox ID-konton. Registrera den omdirigerings-URI som visas för varje leverantör hos leverantören. Du hittar den under :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Knapparna är till för personer som loggar in i dina appar, på inloggningssidorna för :part1 :part2. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Personen blir ägare till :part1 och du blir administratör. Bara den nya ägaren kan överföra ägarskapet tillbaka.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Appen har behörighetsområden för flera API:er: :part1 :part2. En token gäller för ett API åt gången, så appen anger det önskade API:et med parametern :part3. En begäran om behörighetsområden för två API:er samtidigt nekas.',
    'this_console_is_your_workspace_its_projects_team_keys_a_66180b31' => 'Den här konsolen är din arbetsyta med projekt, team, nycklar och fakturering. Hur personer loggar in i dina appar, inklusive :part1, konfigureras för varje miljö i dess egen konsol.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Den här åtgärden kräver en persons godkännande för dessa åtkomstuppgifter, men ingen person finns registrerad för att ge det. Utför åtgärden i konsolen eller skapa en nyckel där så att ägaren kan godkänna den.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Den här installationen skickar bara SMS till :part1. Nummer i :part2 kan därför inte ta emot koder förrän de ingår i CBOX_ID_SMS_ALLOWED_COUNTRIES.',
    'this_environment_s_issuer_discovery_and_jwks_are_served_06e9c844' => 'Miljöns utfärdare, discovery och JWKS finns på :part1 :part2. Rikta värdnamnet mot din ingress och terminera TLS där.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'Miljöns egen utfärdare – adressen som ett SDK använder för discovery och värdet i claim-fältet :part1.',
    'this_person_is_the_only_owner_of_part1_organization_s_p_662dfa99' => 'Personen är ensam ägare till :part1 organisation(er): :part2. Överför ägarskapet innan personen raderas.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Manuellt angivna scopes (:part1) saknar ägare. De skickas oförändrade och aldrig med ett registrerat API som målgrupp.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'E-postmeddelandet kunde inte skickas just nu eftersom installationen inte når sin e-postserver. Försök igen senare. En administratör kan också bekräfta din adress med `php artisan cbox-id:users:confirm-email`.',
    'we_have_sent_a_few_links_already_try_again_in_part1_sec_a84fe552' => 'Vi har redan skickat flera länkar. Försök igen om :part1 sekunder eller kontrollera skräppostmappen under tiden.',
    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Vi skickade en länk till :part1. När du öppnar den skapas din första miljö: din identitetsleverantör i produktion, med egen inloggning, användare och signeringsnycklar. Sedan kommer du direkt tillbaka hit. Länken är giltig i 24 timmar.',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Åtgärderna som väntar på godkännande. Agenten får ett 202-svar med en kort kod. Du godkänner på telefonen eller under :part1 :part2, och agenten upprepar begäran en enda gång.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Skriva och ta bort relationstupler: vem som äger, redigerar eller visar vilka resurser i appen. Åtkomsten i appen ges eller återkallas direkt när ändringen skrivs.',
    'you_are_signed_in_part1_but_your_account_does_not_admin_7c479112' => 'Du är inloggad :part1, men kontot får inte administrera :part2. Miljökonsolen kan öppnas av ägare, administratörer och utvecklare i arbetsytan som miljön tillhör.',
    'you_have_no_environment_to_open_yet_part1_part2_part3_t_26e057f8' => 'Du har ännu ingen miljö att öppna. :part1 :part2 :part3 för att skapa en, eller be en arbetsyteägare om åtkomst.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Inloggningssidan får en länk för att skapa ett konto, och appar kan skicka personer direkt till registrering med :part1.',
    'social_provider_enabled_environment' => ':provider är nu tillgänglig på alla inloggningssidor i den här miljön.',
    'social_provider_enabled_organization' => ':provider är nu tillgänglig på inloggningssidan för :organization.',
    'social_provider_enabled_current_organization' => ':provider är nu tillgänglig på organisationens inloggningssida.',
    'webhook_subscribed_events_count' => 'Prenumererade händelser: :count',
    'sms_enabled_country_count' => 'SMS-koder är aktiverade. Tillåtna länder: :count.',
